<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Log in</title>
<style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:radial-gradient(circle at 80% 10%,#dcefe6,transparent 35%),#f5f7f2;color:#17211f;font-family:"DM Sans","Segoe UI",sans-serif}.box{width:min(390px,calc(100% - 32px));padding:32px;border:1px solid #dfe7e1;border-radius:8px;background:#fff;box-shadow:0 18px 45px #17211f14}h1{margin:0 0 8px;font:400 2.5rem Georgia,serif}.muted{color:#68736f}.error{padding:10px;border-radius:5px;color:#8b2e29;background:#f9e6e4}label{display:block;margin:18px 0 7px;color:#68736f;font-size:.75rem;font-weight:800;text-transform:uppercase}input{width:100%;padding:11px;border:1px solid #dfe7e1;border-radius:5px;box-sizing:border-box;font:inherit}button{width:100%;margin-top:22px;padding:12px;border:0;border-radius:5px;color:#fff;background:#176b5b;font:inherit;font-weight:800}a{color:#176b5b}</style></head>
